   AVVIKELSE: --p-fill/--p-thin/--p-fall är inherits:false (planens egna
   @property-rader), så en deklaration på #process ärvs ALDRIG ner till
   dessa efterkommande - .p-live/.contour/.guide/.hatch/.measure ligger
   alla under #process men utanför dess egen inheritance-kedja för en
   inherits:false-egenskap. MÄTT vid ?preview=process-05: klippet löste
   till 100% (p-fill=0, initialvärdet) trots att #process:s beräknade
   värde var 0,5. Fixen är att skriva HELA clamp()-uttrycket ur --sc-ps
   (som ÄR inherits:true) direkt på varje ställe som använder det, i
   stället för att gå via en delad lokal. */
.process-sheet .p-live{
  clip-path:inset(0 0 calc((1 - clamp(0,calc((var(--sc-ps,0) - 0.55) / 0.09),1)) * 100%) 0);
  filter:grayscale(1) contrast(1.05);}

/* s-process-06: konturernas viktfall (rad 5) och hjälplinjer/skraffering
   som tonar till 0,35 opacitet (målbildstabellens exakta ord: bara
   hjälplinjer och skraffering, inte måttlinjer eller ledare). */
.process-sheet .contour{stroke-width:calc(var(--contour-line) - 0.75px * clamp(0,calc((var(--sc-ps,0) - 0.64) / 0.06),1));}
.process-sheet .guide,.process-sheet .hatch{opacity:calc(1 - 0.65 * clamp(0,calc((var(--sc-ps,0) - 0.64) / 0.06),1));}

/* --- per-bana fönster, id för id, i ritordningen. Varje fönster börjar
   där föregående slutar (feel check, plan 010 § Verification): ingen
   bana ritas samtidigt som en annan. */
#p-outline{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.19) / 0.045),1);}
/* #p-mark är ett <use> mot det befintliga ordmärket (alunix-mark-path,
   index.html rad ~893), inte en duplicerad path: <use> saknar
   pathLength-stöd (SVG-specen), så dash-draw-tekniken funkar inte på den.
   En opacitetston, samma enhet som utropen, är den ärliga
   förenklingen för ett 36-units hörnmärke. */
.process-sheet #p-mark{fill:none;stroke:var(--hair-ink);
  stroke-width:var(--contour-hair);
  --p-t:clamp(0,calc((var(--sc-ps,0) - 0.235) / 0.045),1);
  opacity:var(--p-t);}

#p-guides{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.28) / 0.03),1);}
#p-dim-width{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.31) / 0.03),1);}
#p-stations{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.34) / 0.03),1);}
#p-m320,#p-m768,#p-m1440{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.35) / 0.02),1);}

#p-opening{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.37) / 0.03),1);}
#p-dim-gutter{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.40) / 0.03),1);}
#p-lead-169{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.43) / 0.03),1);}
#p-c-gutter{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.43) / 0.02),1);}
#p-c-169{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.46) / 0.02),1);}
/* Leddoten saknade en egen fönsterdeklaration och syntes hela vägen från
   ps 0 (mätt vid ?preview=process-01). Delar --c-169:s fönster: dot och
   etikett landar tillsammans. */
#p-dot-169{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.46) / 0.02),1);opacity:var(--p-t);}

#p-hatch{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.46) / 0.03),1);}
#p-ledgers{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.49) / 0.03),1);}
#p-dim-row{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.52) / 0.03),1);}
#p-c-row{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.55) / 0.02),1);}

#p-title{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.73) / 0.04),1);}
#p-rev{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.77) / 0.04),1);}
#p-c-rev{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.81) / 0.02),1);}

/* device-tabellens rad 9: will-change bara via klass, satt av readState,
   genom befintlig rAF-läsare. Ingen vilande promovering. */
.process.is-drawing .draw{will-change:stroke-dashoffset;}

/* Under 899 px byts arket till den reducerade planschen (K3-r8/index.html
   rad 389-476, samma teknik): färre banor, egen viewBox (satt i JS,
   plansch()-funktionen, eftersom viewBox inte är ett CSS-attribut),
   d:path() för de tre kvarvarande geometrierna. <text>s x/y är
   presentationsattribut och kan INTE sättas i CSS (K3-r8/index.html
   rad 413-417: en CSS-regel mot dem ignoreras tyst) - måttsiffrornas
   OCH de två kvarvarande utropens (16:9, A) x/y flyttas därför i JS,
   samma funktion som byter viewBox. */
@media (max-width:899px){
  .process-stage{position:static;height:auto;flex-direction:column;
    align-items:stretch;padding-inline:var(--rail-x);gap:24px;}
  .process-sheet{width:100%;height:auto;aspect-ratio:320/640;}
  .process-steps{position:static;width:auto;max-width:none;height:auto;
    display:flex;flex-direction:column;gap:clamp(28px,6vh,56px);}
  .process-steps li{position:static;opacity:1 !important;}

  #p-guides,#p-hatch,#p-ledgers,#p-dim-row,#p-dim-gutter,#p-stations,
  #p-c-gutter,#p-c-row{display:none;}

  #p-outline{d:path("M0.5 0.5 H319.5 V639.5 H0.5 Z");}
  #p-opening{d:path("M24 150 H296 V303 H24 Z");}
  /* Calyx-bilden och dess clipPath var kvar på desktop-koordinaterna
     (270,96,538,303) under den mobila viewBoxen (0 0 320 640): bilden
     blödde ut till höger om arket i stället för att fylla öppningen.
     Samma rektangel som #p-opening ovan, 272x153 = 16:9. */
  #p-open-rect,#p-live-img{x:24px;y:150px;width:272px;height:153px;}
  #p-dim-width{d:path("M0 505 H320");}
  #p-lead-169{d:path("M296 150 L306 132 H312");}
  #p-title{d:path("M112 530 H296 V596 H112 Z M112 552 H296 M112 574 H296");}

