/* ---------------------------------------------------------- process
   PLAN 010, R5. PROCESS: ett ritat ark i sju tillstånd, INTE fyra
   ikonkort eller en tidslinje med punkter. Formen lånad ur
   board/cells/K3-r8/index.html, aldrig som sida: Calyx maskas in som
   bild i ett <clipPath>, inte som en tredje live-ram. Sektionens enda
   höjdmekanism är CSS: min-height:300svh på sektionen, position:sticky
   på arket. Ingen JS rör höjden. */
.process{background:var(--bg);color:var(--ink);min-height:300svh;
  padding-block:0;position:relative;}
.process-kicker{padding:clamp(48px,8vh,88px) var(--rail-x) 0;}
.process-title{font-family:var(--f-display);font-weight:700;
  font-size:clamp(1.3rem,1.8vw,1.6rem);letter-spacing:-.01em;
  color:var(--ink);max-width:32ch;
  padding:.6rem var(--rail-x) 0;}

.process-stage{position:sticky;top:202px;height:495px;
  display:flex;align-items:center;justify-content:space-between;
  padding-inline:var(--rail-x) 80px;}

.process-steps{position:relative;width:384px;max-width:384px;
  height:495px;flex:none;list-style:none;margin:0;padding:0;}
.process-steps li{position:absolute;inset:0;
  display:flex;flex-direction:column;justify-content:center;gap:.6rem;}
.process-step-title{font-family:var(--f-display);font-weight:700;
  font-size:clamp(1.4rem,2.2vw,2rem);letter-spacing:-.01em;
  text-transform:uppercase;color:var(--ink);}
.process-q{font-family:var(--font);font-weight:600;font-size:16px;
  color:var(--ink);max-width:34ch;}
.process-a{font-family:var(--font);font-weight:300;font-size:16px;
  color:rgba(22,20,15,.78);max-width:34ch;}

/* Sju fönster, ingen overlap: samma formel som K3:s utrop (index.html:
   rad ~955, "opacitet läser --sc-ps") men F-014:s striktare regel gäller
   hela vägen. --step-start/--step-end sätts per <li> som inline custom
   properties i markupen (statiska HTML-tal, ingen JS). Sista steget
   håller: bara in-klampen, ingen ut-klamp (device-tabellens rad 7). */
.process-steps li{
  opacity:min(
    clamp(0,calc((var(--sc-ps,0) - var(--step-start)) / 0.02),1),
    clamp(0,calc((var(--step-end) + 0.02 - var(--sc-ps,0)) / 0.02),1)
  );}
.process-steps li[data-step="07"]{
  opacity:clamp(0,calc((var(--sc-ps,0) - var(--step-start)) / 0.02),1);}

.process-sheet{width:880px;height:495px;flex:none;}

/* --- linjehierarkin, K3:s klasser, V3c:s egna tokens (index.html:143-149) */
.process-sheet .contour{fill:none;stroke:var(--ink);stroke-width:var(--contour-line);}
.process-sheet .dimline{fill:none;stroke:var(--hair-ink);stroke-width:var(--contour-hair);}
.process-sheet .guide{fill:none;stroke:var(--hair-ink);stroke-width:var(--contour-hair);
  stroke-dasharray:var(--contour-dash);}
.process-sheet .leader{fill:none;stroke:var(--hair-ink);stroke-width:var(--contour-hair);}
.process-sheet .hatch{fill:url(#p-hatch-pattern);stroke:none;}
.process-sheet .leaddot{fill:var(--hair-ink);stroke:none;}
.process-sheet #p-hatch-pattern line{stroke:var(--hair-ink);}
.process-sheet path,.process-sheet rect{stroke-linecap:butt;stroke-linejoin:miter;}

/* --- ritmekaniken. pathLength="1" normaliserar varje bana; enheten
   *1px på stroke-dashoffset är obligatorisk (K3-r8/index.html:263-268:
   utan den serialiserar Chromium "calc(1px)" och "0%" som två olika
   typer och motion_probe rapporterar DEAD på en bana som ritar sig
   korrekt på skärmen). En streckad hjälplinje kan inte dash-ritas
   (dasharray gör redan ett jobb), så guide/stations/ledgers/hatch
   avslöjas med clip-path i stället. */
.process-sheet .draw{stroke-dasharray:1px;stroke-dashoffset:calc((1 - var(--p-l)) * 1px);
  /* Markörer (pilspetsar) positioneras på banans vertex, INTE på den
     synliga stroken - stroke-dashoffset klipper dem inte. MÄTT vid
     ?preview=process-01: pilspetsarna på #p-dim-gutter syntes trots
     --p-l = 0. En snäpp-opacitet som går 0 -> 1 inom bråkdelen av en
     procent av fönstret döljer dem tills banan faktiskt börjat rita,
     utan att röra den riktiga rittempot. */
  opacity:clamp(0,calc(var(--p-l) * 9999),1);}
.process-sheet .wipe{clip-path:inset(0 calc((1 - var(--p-l)) * 100%) 0 0);}

.process-sheet .callout{font-family:var(--font);font-weight:600;font-size:12px;
  letter-spacing:.16em;text-transform:uppercase;fill:var(--hair-ink);
  opacity:var(--p-t);}
.process-sheet .measure{font-family:var(--f-display);font-weight:700;
  font-size:44px;fill:var(--c-accent);font-variant-numeric:tabular-nums;
  opacity:var(--p-t);transform-box:fill-box;
  /* 44 -> 12px = faktor 1 - 0.7273. transform-box:fill-box är inte
     valfritt: utan den skalar siffran mot SVG:ns user-space-nollpunkt,
     inte mot sin egen box (samma fälla som K3 dokumenterar, index.html
     rad ~288-293). */
  transform:scale(calc(1 - 0.7273 * clamp(0,calc((var(--sc-ps,0) - 0.64) / 0.09),1)));}
#p-m320,#p-m768{transform-origin:50% 100%;}
#p-m1440{transform-origin:100% 100%;}

/* s-process-05: den fyllda öppningen. Filtret ligger på ett 538x303-
   element, aldrig helskärm (performance.md § 3).
   AVVIKELSE: --p-fill/--p-thin/--p-fall är inherits:false (planens egna
   @property-rader), så en deklaration på #process ärvs ALDRIG ner till
   dessa efterkommande - .p-live/.contour/.guide/.hatch/.measure ligger
   alla under #process men utanför dess egen inheritance-kedja för en
   inherits:false-egenskap. MÄTT vid ?preview=process-05: klippet löste
   till 100% (p-fill=0, initialvärdet) trots att #process:s beräknade
   värde var 0,5. Fixen är att skriva HELA clamp()-uttrycket ur --sc-ps
   (som ÄR inherits:true) direkt på varje ställe som använder det, i
   stället för att gå via en delad lokal. */
.process-sheet .p-live{
  clip-path:inset(0 0 calc((1 - clamp(0,calc((var(--sc-ps,0) - 0.55) / 0.09),1)) * 100%) 0);
  filter:grayscale(1) contrast(1.05);}

/* s-process-06: konturernas viktfall (rad 5) och hjälplinjer/skraffering
   som tonar till 0,35 opacitet (målbildstabellens exakta ord: bara
   hjälplinjer och skraffering, inte måttlinjer eller ledare). */
.process-sheet .contour{stroke-width:calc(var(--contour-line) - 0.75px * clamp(0,calc((var(--sc-ps,0) - 0.64) / 0.06),1));}
.process-sheet .guide,.process-sheet .hatch{opacity:calc(1 - 0.65 * clamp(0,calc((var(--sc-ps,0) - 0.64) / 0.06),1));}

/* --- per-bana fönster, id för id, i ritordningen. Varje fönster börjar
   där föregående slutar (feel check, plan 010 § Verification): ingen
   bana ritas samtidigt som en annan. */
#p-outline{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.19) / 0.045),1);}
/* #p-mark är ett <use> mot det befintliga ordmärket (alunix-mark-path,
   index.html rad ~893), inte en duplicerad path: <use> saknar
   pathLength-stöd (SVG-specen), så dash-draw-tekniken funkar inte på den.
   En opacitetston, samma enhet som utropen, är den ärliga
   förenklingen för ett 36-units hörnmärke. */
.process-sheet #p-mark{fill:none;stroke:var(--hair-ink);
  stroke-width:var(--contour-hair);
  --p-t:clamp(0,calc((var(--sc-ps,0) - 0.235) / 0.045),1);
  opacity:var(--p-t);}

#p-guides{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.28) / 0.03),1);}
#p-dim-width{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.31) / 0.03),1);}
#p-stations{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.34) / 0.03),1);}
#p-m320,#p-m768,#p-m1440{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.35) / 0.02),1);}

#p-opening{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.37) / 0.03),1);}
#p-dim-gutter{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.40) / 0.03),1);}
#p-lead-169{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.43) / 0.03),1);}
#p-c-gutter{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.43) / 0.02),1);}
#p-c-169{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.46) / 0.02),1);}
/* Leddoten saknade en egen fönsterdeklaration och syntes hela vägen från
   ps 0 (mätt vid ?preview=process-01). Delar --c-169:s fönster: dot och
   etikett landar tillsammans. */
#p-dot-169{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.46) / 0.02),1);opacity:var(--p-t);}

#p-hatch{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.46) / 0.03),1);}
#p-ledgers{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.49) / 0.03),1);}
#p-dim-row{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.52) / 0.03),1);}
#p-c-row{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.55) / 0.02),1);}

#p-title{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.73) / 0.04),1);}
#p-rev{--p-l:clamp(0,calc((var(--sc-ps,0) - 0.77) / 0.04),1);}
#p-c-rev{--p-t:clamp(0,calc((var(--sc-ps,0) - 0.81) / 0.02),1);}

/* device-tabellens rad 9: will-change bara via klass, satt av readState,
   genom befintlig rAF-läsare. Ingen vilande promovering. */
.process.is-drawing .draw{will-change:stroke-dashoffset;}

/* Under 899 px byts arket till den reducerade planschen (K3-r8/index.html
   rad 389-476, samma teknik): färre banor, egen viewBox (satt i JS,
   plansch()-funktionen, eftersom viewBox inte är ett CSS-attribut),
   d:path() för de tre kvarvarande geometrierna. <text>s x/y är
   presentationsattribut och kan INTE sättas i CSS (K3-r8/index.html
   rad 413-417: en CSS-regel mot dem ignoreras tyst) - måttsiffrornas
   OCH de två kvarvarande utropens (16:9, A) x/y flyttas därför i JS,
   samma funktion som byter viewBox. */
@media (max-width:899px){
  .process-stage{position:static;height:auto;flex-direction:column;
    align-items:stretch;padding-inline:var(--rail-x);gap:24px;}
  .process-sheet{width:100%;height:auto;aspect-ratio:320/640;}
  .process-steps{position:static;width:auto;max-width:none;height:auto;
    display:flex;flex-direction:column;gap:clamp(28px,6vh,56px);}
  .process-steps li{position:static;opacity:1 !important;}

  #p-guides,#p-hatch,#p-ledgers,#p-dim-row,#p-dim-gutter,#p-stations,
  #p-c-gutter,#p-c-row{display:none;}

  #p-outline{d:path("M0.5 0.5 H319.5 V639.5 H0.5 Z");}
  #p-opening{d:path("M24 150 H296 V303 H24 Z");}
  /* Calyx-bilden och dess clipPath var kvar på desktop-koordinaterna
     (270,96,538,303) under den mobila viewBoxen (0 0 320 640): bilden
     blödde ut till höger om arket i stället för att fylla öppningen.
     Samma rektangel som #p-opening ovan, 272x153 = 16:9. */
  #p-open-rect,#p-live-img{x:24px;y:150px;width:272px;height:153px;}
  #p-dim-width{d:path("M0 505 H320");}
  #p-lead-169{d:path("M296 150 L306 132 H312");}
  #p-title{d:path("M112 530 H296 V596 H112 Z M112 552 H296 M112 574 H296");}
  #p-rev{x:112px;y:530px;width:184px;height:22px;}
  #p-m320,#p-m768,#p-m1440{font-size:34px;}
}

